window.NPC_CHUNK_155 = [{"name":"Hakotep I","cr":19,"xp":204800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"sorcerer","level":18}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["human"],"templates_applied":"mummy lord","init":6,"senses":["darkvision 60 ft."],"auras":["great despair (30 ft., DC 27)"],"ac":37,"ac_touch":16,"ac_flat_footed":34,"ac_mods":"+4 armor, +3 deflection, +2 Dex, +1 dodge, +13 natural, +4 shield","hp":260,"hd":"18d6+195","hd_value":18,"fort":18,"ref":14,"will":17,"defensive_abilities":["channel resistance +4","rejuvenation"],"dr":"10/-","immunities":["cold","electricity","undead traits"],"resists":["fire 10"],"speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"flail of kings +19 (1d8+10/19-20 plus insidious mummy rot) or slam +17 (1d6+12 plus insidious mummy rot)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel rot"},{"type":"insidious mummy rot","details":"DC 27"},{"type":"sandstorm wrath","details":"3/day, 12d8 fire and slashing, DC 27"},{"type":"undead mastery","details":"DC 27"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"2/day","spells":[{"spell":"elemental blast","details":"18d6 electricity"}]},{"frequency":"11/day","spells":[{"spell":"elemental ray","details":"1d6+9 electricity"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":18,"spellsknown_concentration":26,"spellsknown":[{"spell_level":9,"spell_slots":3,"spells":[{"spell":"meteor swarm"}]},{"spell_level":8,"spell_slots":6,"spells":[{"spell":"polar ray"},{"spell":"stormbolts"},{"spell":"summon monster VIII"}]},{"spell_level":7,"spell_slots":7,"spells":[{"spell":"deflection"},{"spell":"elemental body IV"},{"spell":"mass hold person"},{"spell":"prismatic spray"}]},{"spell_level":6,"spell_slots":7,"spells":[{"spell":"chain lightning"},{"spell":"elemental body III"},{"spell":"sirocco"},{"spell":"tar pool"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"cone of cold"},{"spell":"elemental body II"},{"spell":"mind fog"},{"spell":"sonic thrust"},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":8,"spells":[{"spell":"ball lightning"},{"spell":"boneshatter"},{"spell":"crushing despair"},{"spell":"elemental body I"},{"spell":"enervation"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"elemental aura"},{"spell":"howling agony"},{"spell":"lightning bolt"},{"spell":"protection from energy"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"blindness/deafness"},{"spell":"bull's strength"},{"spell":"false life"},{"spell":"hideous laughter"},{"spell":"mirror image"},{"spell":"scorching ray"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"burning hands"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"shield"},{"spell":"shocking grasp"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"prestidigitation"},{"spell":"ray of frost"},{"spell":"read magic"},{"spell":"touch of fatigue"}]}],"bloodline":"elemental (air)","strength":26,"dexterity":14,"intelligence":12,"wisdom":10,"charisma":26,"baseatk":9,"cmb":17,"cmd":33,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Elemental Focus (electricity)"},{"feat":"Eschew Materials","type":"bonus"},{"feat":"Greater Spell Focus (evocation)"},{"feat":"Improved Critical (flail)"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes","type":"bonus"},{"feat":"Quicken Spell"},{"feat":"Spell Focus (enchantment)"},{"feat":"Spell Focus (evocation)"},{"feat":"Spell Penetration"},{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Fly","value":14},{"skill":"Intimidate","value":28},{"skill":"Knowledge (arcana)","value":14},{"skill":"Knowledge (nobility)","value":11},{"skill":"Knowledge (religion)","value":14},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":29},{"skill":"Spellcraft","value":14},{"skill":"Stealth","value":10}],"languages":["Ancient Osiriani","Auran"],"sq":["bloodline arcana (change energy damage spells to electricity)","elemental movement"],"special_abilities":[{"type":"Rejuvenation","kind":"Su","details":"One day after Hakotep is destroyed, the necromantic energies within him begin to rebuild his body. This process takes 1d10 days. If the body is destroyed before that time passes, the process starts anew. After this time, Hakotep awakens fully healed. The normal methods for permanently destroying a mummy lord are insufficient to counteract Hakotep's rejuvenation. Only by placing the Mask of the Forgotten Pharaoh on Hakotep's dead body (thus rejoining Hakotep's ka with the other fragments of his soul) can the Sky Pharaoh be permanently destroyed."}],"gear":"amulet of natural armor +4, cloak of resistance +4, crook and flail of kings (+2 thundering flail), khepresh of refuge, gold and emerald necklace (amulet keyed to shield guardians in area E24, worth 20,000 gp), scroll of reverse gravity, scroll of time stop","before_combat":"Hakotep casts mage armor and false life on himself every day. As soon as the stone block in area E21 is opened, Hakotep casts bull's strength, mirror image, and shield.","during_combat":"Hakotep orders two of his shield guardians to guard him (all attacks against Hakotep take a -2 penalty for each golem adjacent to him) while the other two engage opponents in melee. Thereafter, Hakotep concentrates his attacks on the wearer of the Mask of the Forgotten Pharaoh, preferring to use evocation spells he can cast at range, such as meteor swarm, polar ray, prismatic spray, and chain lighting, while taking advantage of the metamagic abilities of his crook and flail of kings.","morale":"The first time Hakotep takes damage in combat, he activates one of his shield guardians' shield other abilities. If reduced to 100 hit points or fewer, Hakotep casts tar pool to entangle as many of the PCs as possible, or casts mass hold person to slow them down. He then flies to reposition himself in the eastern portion of the room, ordering his shield guardian bodyguards to accompany him, and continues throwing spells at opponents. If reduced to 50 hit points or fewer, Hakotep directs him golems to cover his retreat while he flees to the temple of Set (area E9). There, Hakotep kneels before the altar and beseeches Set for aid: \"Father of Darkness! Would you deny your beloved our throne? We call for your aid!\" Set doesn't answer this prayer, and Hakotep makes his final stand in the temple, fighting until destroyed.","source":"AP 84"},{"name":"Queen Neferuset","cr":17,"xp":102400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"oracle","level":17}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human"],"templates_applied":"mummified","init":7,"senses":["darkvision 60 ft."],"auras":["frightful presence (30 ft., DC 16, 1d6 rounds)"],"ac":31,"ac_touch":27,"ac_flat_footed":27,"ac_mods":"+10 armor, +3 deflection, +3 Dex, +1 dodge, +4 natural","hp":216,"hd":"17d8+136","hd_value":17,"fort":14,"ref":13,"will":17,"dr":"5/-","immunities":["undead traits"],"sr":29,"weaknesses":["vulnerable to electricity"],"speed":[{"type":"land","speed":20}],"melee":"slam +14 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burst of vengeance"},{"type":"dust stroke"}],"spellsknown_caster":"oracle","spellsknown_caster_level":17,"spellsknown_concentration":23,"spellsknown":[{"spell_level":8,"spell_slots":4,"spells":[{"spell":"greater planar ally"},{"spell":"mass inflict critical wounds"},{"spell":"orb of the void"},{"spell":"reverse gravity"}]},{"spell_level":7,"spell_slots":6,"spells":[{"spell":"blasphemy"},{"spell":"destruction"},{"spell":"insanity"},{"spell":"mass inflict serious wounds"},{"spell":"word of chaos"}]},{"spell_level":6,"spell_slots":7,"spells":[{"spell":"antilife shell"},{"spell":"harm"},{"spell":"mass inflict moderate wounds"},{"spell":"plague storm"},{"spell":"planar binding"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"feeblemind"},{"spell":"flame strike"},{"spell":"insect plague"},{"spell":"major curse"},{"spell":"mass inflict light wounds"},{"spell":"spell resistance"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"black tentacles"},{"spell":"chaos hammer"},{"spell":"dismissal"},{"spell":"fleshworm infestation"},{"spell":"inflict critical wounds"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"blindness/deafness"},{"spell":"dispel magic"},{"spell":"inflict serious wounds"},{"spell":"invisibility purge"},{"spell":"tongues"},{"spell":"water walk"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"death knell"},{"spell":"desecrate"},{"spell":"dust of twilight"},{"spell":"inflict moderate wounds"},{"spell":"oracle's burden"},{"spell":"silence"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"deathwatch"},{"spell":"divine favor"},{"spell":"doom"},{"spell":"entropic shield"},{"spell":"inflict light wounds"},{"spell":"obscuring mist"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"guidance"},{"spell":"mending"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"spark"},{"spell":"virtue"}]}],"mystery":"Dark Tapestry","strength":14,"dexterity":16,"intelligence":10,"wisdom":14,"charisma":22,"baseatk":12,"cmb":14,"cmd":31,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Extra Revelation"},{"feat":"Greater Spell Focus (necromancy)"},{"feat":"Improved Initiative"},{"feat":"Improved Natural AttackB (slam)"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Spell Focus (evocation)"},{"feat":"Spell Focus (necromancy)"},{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Knowledge (arcana)","value":17},{"skill":"Knowledge (planes)","value":15},{"skill":"Knowledge (religion)","value":15},{"skill":"Spellcraft","value":20},{"skill":"Stealth","value":25},{"skill":"Use Magic Device","value":23}],"languages":["Abyssal","Aklo","Ancient Osiriani","Auran","Common; tongues"],"sq":["oracle's curse (tongues)","revelations (brain drain [17d4, DC 24, 4/day], cloak of darkness [+10 armor, +8 Stealth, 17 hours/day], dweller in darkness, gift of madness [DC 24, 17 rounds, 9/day], interstellar void [17d6, DC 24, 2/day], wings of darkness)"],"gear":"belt of incredible dexterity +2, cloak of resistance +3, headband of alluring charisma +2, ring of protection +3, gold bracelets set with a purple corundum and an unusually large black opal (worth 3,250 gp each), red deshret crown capped by a gold hooded cobra with small rubies for eyes (worth 2,200 gp), gold earrings set with tiny  black star sapphires (worth 2,000 gp for the set), gold pectoral necklace set with black pearls (worth 14,750 gp), 10 black gemstones of various types (worth 50 gp each), powdered lead and platinum (worth 250 gp), silver dust (worth 25 gp), greater bouncing metamagic rod, scroll of dust form, scroll of implosion, wand of deeper darkness (10 charges)","before_combat":"Neferuset uses her wand of deeper darkness in area E13, casts spell resistance, and activates her cloak of darkness revelation.","during_combat":"Neferuset lets her neshmaal allies engage opponents directly while she casts orb of the void. She then tries to disrupt spellcasters by using feeblemind and her gift of madness revelation, utilizing her bouncing metamagic rod when she thinks her target has a strong defense against her spell. If the battle turns in her enemies' favor, she casts destruction against the foe who appears to be the greatest threat, followed by reverse gravity. If forced into melee combat, Neferuset employs her wings of darkness revelation to fly out of reach and casts antilife shell to prevent living foes from approaching her.","morale":"If reduced to 0 hit points, Neferuset isn't actually destroyed. Two hours after her destruction, the canopic jar of unlife in area E14 begins regenerating her undead body. When she regains full strength, Neferuset pursues those who dared to attempt to destroy her, or joins her husband in area E34.","source":"AP 84, Pathfinder RPG Advanced Player's Guide 42, Pathfinder RPG Bestiary 4 196"},{"name":"Mekuhare","cr":20,"xp":307200,"race":"mythic  sphinx","gender":"Male","age_category":"elder","alignment":"NE","size":"Colossal","type":"magical beast","sub_types":["mythic"],"init":1,"senses":["blindsense 30 ft.","darkvision 60 ft.","low-light vision"],"ac":33,"ac_touch":3,"ac_flat_footed":32,"ac_mods":"+1 Dex, +30 natural, -8 size","hp":379,"hd":"22d10+258","hd_value":22,"fort":22,"ref":14,"will":14,"defensive_abilities":["enciphered mind","fearless","fortification (50%)","pure destiny","unchanging"],"dr":"15/adamantine, magic, and epic","immunities":["petrification"],"sr":31,"speed":[{"type":"fly","speed":60,"maneuverability":"poor"},{"type":"land","speed":50}],"melee":"2 claws +32 (3d6+18/19-20/x3 plus grab), 2 wings +27 (2d8+9)","space":"30 ft.","reach":"20 ft.","special_attacks":[{"type":"commune with power"},{"type":"litany of riddles"},{"type":"mythic power","details":"6/day, surge +1d8"},{"type":"mythic spellcasting"},{"type":"pounce"},{"type":"rake","details":"2 claws, 3d6+16"},{"type":"roar"}],"spellsprepared_caster_level":13,"spellsprepared_concentration":20,"spellsprepared":[{"spell_level":7,"spell_slots":2,"spells":[{"spell":"destruction"},{"spell":"jolting portent"}]},{"spell_level":6,"spell_slots":3,"spells":[{"spell":"blade barrier","type":"mythic"},{"spell":"greater dispel magic"},{"spell":"heal"}]},{"spell_level":5,"spell_slots":4,"spells":[{"spell":"flame strike","type":"mythic"},{"spell":"insect plague"},{"spell":"plane shift","type":"mythic"},{"spell":"slay living"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"cure critical wounds"},{"spell":"divine power"},{"spell":"freedom of movement"},{"spell":"summon monster IV"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"bestow curse"},{"spell":"blindness/deafness","type":"mythic"},{"spell":"invisibility purge"},{"spell":"searing light","type":"mythic","count":2},{"spell":"wind wall"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"death knell"},{"spell":"dread bolt"},{"spell":"enthrall"},{"spell":"hold person"},{"spell":"silence","type":"mythic"},{"spell":"sound burst"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"command"},{"spell":"divine favor"},{"spell":"doom"},{"spell":"entropic shield"},{"spell":"obscuring mist"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":4,"spells":[{"spell":"create water"},{"spell":"detect magic"},{"spell":"read magic"},{"spell":"spark"}]}],"strength":46,"dexterity":13,"constitution":29,"intelligence":20,"wisdom":24,"charisma":23,"baseatk":22,"cmb":48,"cmb_special":"+50 bull rush","cmd":59,"cmd_special":"61 vs. bull rush, 63 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Awesome Blow"},{"feat":"Cleave","type":"mythic"},{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Hover"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (claws)","type":"mythic"},{"feat":"Power Attack","type":"mythic"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Diplomacy","value":18},{"skill":"Fly","value":0},{"skill":"Knowledge (arcana, history, planes, religion)","value":15},{"skill":"Knowledge (dungeoneering, engineering, geography, local, nature, nobility)","value":10},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":25},{"skill":"Survival","value":15}],"languages":["Common","Abyssal","Ancient Osiriani","Aquan","Auran","Draconic","Ignan","Sphinx","Terran"],"sq":["enigma","mythic sight","sphinx monolith"],"special_abilities":[{"type":"Enciphered Mind","kind":"Su","details":"Any creature attempting to contact Mekuhare's mind or read his thoughts with a divination spell or similar ability must succeed at a DC 27 Will save or be overwhelmed by the chaos and vast scope of the knowledge within. Those who fail are affected by feeblemind. Mekuhare can suppress this ability at will as a free action. This is a mind-affecting effect, and the save DC is Charisma-based."},{"type":"Enigma","kind":"Su","details":"Mekuhare has removed himself from the mundane world to contemplate the mysteries of the universe-and beyond. To facilitate this, he possesses an uncanny ability to elude detection and discovery by those that could possibly interrupt his meditations. Any creature (other than another sphinx), that leaves line of sight of Mekuhare for more than 1 hour must succeed at a DC 27 Will save or be unable to recall details of the encounter, as if the sphinx had cast modify memory to eliminate all recollection of itself. The exact details of this memory loss are decided by Mekuhare subconsciously during the encounter, and he may eliminate up to an hour of memories. This is a mind-affecting compulsion effect and the save DC is Charisma-based."},{"type":"Litany of Riddles","kind":"Su","details":"As a standard action, Mekuhare can telepathically project a befuddling series of riddles, puzzles, and paradoxes at all creatures in a 60-foot cone. Creatures caught in this effect must succeed at a DC 27 Will save or be stunned for 1d4 rounds. Creatures that succeed on their saving throw glean snippets of lore from this brush with the sphinx's mind, granting them a +5 insight bonus on all Knowledge checks for 1 hour and the ability to attempt Knowledge checks with a DC higher than 10 untrained. Once a creature successfully saves against this ability, it can't be affected by Mekuhare's litany of riddles for 24 hours. This is a mind-affecting effect and the save DC is Charisma-based."},{"type":"Roar","kind":"Su","details":"Mekuhare can roar up to three times per day as a standard action. Each successive roar has a different effect, depending upon whether it is the first, second, or third of the sphinx's roars for that day. Each of these roars is a sonic effect that fills a 60-foot-radius burst, centered on Mekuhare; the save DCs are Charisma-based. Sphinxes are immune to all of the effects of Mekuhare's roars. First Roar: Affected creatures become frightened for 2d6 rounds (DC 27 Will negates). This is a mind-affecting fear effect in addition to being a sonic effect. Second Roar: Affected creatures are paralyzed with fear and deafened for 1d4 rounds (DC 27 Will negates). This is a mind-affecting fear effect in addition to being a sonic effect. Third Roar: Affected creatures take a 2d4 penalty to Strength for 2d4 rounds and take 2d8 points of sonic damage. Creatures smaller than the sphinx are knocked prone. A DC 27 Fortitude save negates the Strength penalty and being knocked prone. The save DC is Charisma-based."},{"type":"Spells","details":"Mekuhare casts divine spells as a 13th-level cleric. He doesn't gain access to domains or other cleric abilities."},{"type":"Sphinx Monolith","kind":"Su","details":"Mekuhare can enter a state of suspended animation and transform his massive body into a stone monument. This transformation takes 1 minute to complete, during which Mekuhare is immobile. Once he transforms into his monolith form, Mekuhare's body hardens to stone, granting him hardness 30 and 350 hit points. If his stony body is reduced to 0 hit points, it is destroyed and Mekuhare is slain. While transformed, Mekuhare doesn't need to breathe, eat, drink, or sleep. He is aware of his surroundings and can use astral projection at will when in this form. Anytime Mekuhare's body takes damage while he's using astral projection, his astral form immediately becomes aware that he is in danger and can, as a free action, end the astral projection and begin reverting back to his natural form (though the process still takes 1 minute). When Mekuhare ends his transformation, he is immediately healed of all hit point damage he may have sustained while transformed. Mekuhare can remain in his sphinx monolith form indefinitely."}],"source":"AP 84, Pathfinder Adventure Path #83 90; Pathfinder RPG Mythic Adventures 226"},{"name":"Tower Guard","cr":3,"xp":800,"race":"Ratfolk","age_category":"Adult","classes":[{"class":"fighter","level":2},{"class":"rogue","level":2}],"alignment":"N","size":"Small","type":"humanoid","sub_types":["ratfolk"],"init":8,"senses":["darkvision 60 ft."],"ac":19,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+3 armor, +4 Dex, +1 shield, +1 size","hp":30,"hd":"2d10+2d8+6","hd_value":4,"fort":5,"ref":8,"will":2,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","evasion"],"speed":[{"type":"land","speed":20}],"melee":"short sword +5 (1d4+1/19-20)","ranged":"mwk composite longbow +10 (1d6+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"},{"type":"swarming"}],"strength":12,"dexterity":18,"constitution":12,"intelligence":12,"wisdom":13,"charisma":8,"baseatk":3,"cmb":3,"cmd":17,"feats":[{"feat":"Improved Initiative"},{"feat":"Point-Blank Shot"},{"feat":"Rapid Shot"},{"feat":"Weapon Focus (composite longbow)"}],"skills":[{"skill":"Climb","value":4},{"skill":"Craft (alchemy)","value":7},{"skill":"Disable Device","value":7},{"skill":"Handle Animal","value":3,"special":"+4 to influence rodents"},{"skill":"Knowledge (dungeoneering)","value":6},{"skill":"Knowledge (engineering)","value":6},{"skill":"Knowledge (local)","value":5},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":8},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":11},{"skill":"Survival","value":8},{"skill":"Use Magic Device","value":5}],"languages":["Common","Tian"],"sq":["rogue talents (slow reactions)","trapfinding +1"],"special_abilities":[{"type":"Swarming","kind":"Ex","details":"Ratfolk are used to living and fighting communally, and are adept at swarming foes for their own gain and their foes' detriment. Up to two ratfolk can share the same square at the same time. If two ratfolk in the same square attack the same foe, they are considered to be flanking that foe as if they were in two opposite squares."}],"gear":"masterwork studded leather, buckler, masterwork composite longbow (+1 Str) with 20 arrows, short sword, cloak of resistance +1, 18 gp, potions of cure moderate wounds (2), alchemist's fire, blunt arrows* (20), smokestick, tanglefoot bag","before_combat":"The ratfolk guards attempt to identify anyone approaching their tower. Unless the PCs manage to convince the guards to engage in diplomacy, the guards open fire from behind the improved cover of their arrow slits. The arrow slits grant the ratfolk a +8 bonus to AC, a +4 bonus on Reflex saves, and the benefits of the improved evasion class feature.","during_combat":"The ratfolk guards retreat deeper into the tower as needed to avoid melee for as long as possible. Should they be forced into melee, they use their swarming tactics to confuse their enemies. If one of their foes appears near death, they switch to nonlethal attacks (such as their blunt arrows) to drop their opponent, as their primary goal is simply to repel intruders.","morale":"If brought below 10 hit points, the ratfolk guards attempt to surrender with the hopes of escaping their capturers and retreating to their captain's office.","source":"PFS S3-20, Pathfinder RPG Bestiary 3 231"},{"name":"Senior Tower Guard","cr":6,"xp":2400,"race":"Ratfolk","age_category":"Adult","classes":[{"class":"fighter","level":4},{"class":"rogue","level":3}],"alignment":"N","size":"Small","type":"humanoid","sub_types":["ratfolk"],"init":8,"senses":["darkvision 60 ft."],"ac":20,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+4 armor, +4 Dex, +1 shield, +1 size","hp":50,"hd":"4d10+3d8+11","hd_value":7,"fort":7,"ref":9,"will":4,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","evasion","trap sense +1"],"speed":[{"type":"land","speed":20}],"melee":"short sword +8 (1d4+1/19-20)","ranged":"+1 composite longbow +13 (1d6+4/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"},{"type":"swarming"}],"strength":12,"dexterity":18,"constitution":12,"intelligence":12,"wisdom":13,"charisma":8,"baseatk":6,"cmb":6,"cmd":20,"feats":[{"feat":"Deadly Aim"},{"feat":"Improved Initiative"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Weapon Focus (longbow)"},{"feat":"Weapon Specialization (longbow)"}],"skills":[{"skill":"Climb","value":5},{"skill":"Craft (alchemy)","value":7},{"skill":"Disable Device","value":8},{"skill":"Handle Animal","value":4,"special":"+4 to influence rodents"},{"skill":"Knowledge (dungeoneering)","value":7},{"skill":"Knowledge (engineering)","value":7},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":11},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":12},{"skill":"Survival","value":11},{"skill":"Use Magic Device","value":7}],"languages":["Common","Tian"],"sq":["armor training 1","rogue talents (slow reactions)","trapfinding +1"],"special_abilities":[{"type":"Swarming","kind":"Ex","details":"Ratfolk are used to living and fighting communally, and are adept at swarming foes for their own gain and their foes' detriment. Up to two ratfolk can share the same square at the same time. If two ratfolk in the same square attack the same foe, they are considered to be flanking that foe as if they were in two opposite squares."}],"gear":"masterwork chain shirt, masterwork buckler, +1 composite longbow (+1 Str) with 20 arrows, short sword, cloak of resistance +1, 163 gp, potion of cat's grace, potions of cure serious wounds (2), alchemist's fire, blunt arrows* (20), smokestick, tanglefoot bag, thunderstone","before_combat":"The ratfolk guards attempt to identify anyone approaching their tower. Unless the PCs manage to convince the guards to engage in diplomacy, the guards open fire from behind the improved cover of their arrow slits. The arrow slits grant the ratfolk a +8 bonus to AC, a +4 bonus on Reflex saves, and the benefits of the improved evasion class feature.","during_combat":"The ratfolk guards retreat deeper into the tower as needed to avoid melee for as long as possible. Should they be forced into melee, they use their swarming tactics to confuse their enemies. If one of their foes appears near death, they switch to nonlethal attacks (such as their blunt arrows) to drop their opponent as their primary goal is simply to repel intruders.","morale":"If brought below 10 hit points, the ratfolk guards attempt to retreat to their captain's office.","source":"PFS S3-20, Pathfinder RPG Bestiary 3 231"},{"name":"Tower Captain","cr":10,"xp":9600,"race":"ratfolk","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":6},{"class":"rogue","level":5}],"alignment":"N","size":"Small","type":"humanoid","sub_types":["ratfolk"],"init":8,"senses":["darkvision 60 ft."],"ac":23,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+6 armor, +4 Dex, +2 shield, +1 size","hp":98,"hd":"6d10+5d8+39","hd_value":11,"fort":10,"ref":11,"will":7,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2","evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":20}],"melee":"mwk short sword +12 (1d4+1/19-20)","ranged":"+1 composite longbow +17 (1d6+5/19-20/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+3d6"},{"type":"swarming"},{"type":"weapon training","details":"bows +1"}],"strength":12,"dexterity":18,"constitution":16,"intelligence":12,"wisdom":12,"charisma":8,"baseatk":9,"cmb":9,"cmd":23,"feats":[{"feat":"Deadly Aim"},{"feat":"Improved Critical (longbow)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Quick Draw"},{"feat":"Rapid Shot"},{"feat":"Weapon Focus (longbow)"},{"feat":"Weapon Specialization (longbow)"}],"skills":[{"skill":"Climb","value":5},{"skill":"Craft (alchemy)","value":9},{"skill":"Diplomacy","value":8},{"skill":"Disable Device","value":8},{"skill":"Handle Animal","value":3,"special":"+4 to influence rodents"},{"skill":"Intimidate","value":5},{"skill":"Knowledge (dungeoneering)","value":9},{"skill":"Knowledge (engineering)","value":8},{"skill":"Knowledge (local)","value":8},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":15},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":12},{"skill":"Survival","value":14},{"skill":"Use Magic Device","value":5}],"languages":["Common","Tian"],"sq":["armor training 1","rogue talents (combat trick, slow reactions)","trapfinding +2"],"special_abilities":[{"type":"Swarming","kind":"Ex","details":"Ratfolk are used to living and fighting communally, and are adept at swarming foes for their own gain and their foes' detriment. Up to two ratfolk can share the same square at the same time. If two ratfolk in the same square attack the same foe, they are considered to be flanking that foe as if they were in two opposite squares."}],"gear":"+2 mithral chain shirt, +1 buckler, +1 composite longbow with 20 arrows, masterwork short sword, belt of mighty constitution +2, cloak of resistance +1, dust of tracelessness, 15 gp, potion of blur, potions of cure serious wounds (2), alchemist's fire, tanglefoot bag","before_combat":"The tower captain positions himself so that his guards are between him and the PCs.","during_combat":"The ratfolk captain attempts to stay out of melee for as long as possible, instead putting his years of training with the longbow to use. Should he be forced into melee, he draws his short sword and swarms with any remaining guards.","morale":"If brought below 25 hit points, the ratfolk captain attempts to surrender.","source":"PFS S3-20, Pathfinder RPG Bestiary 3 231"},{"name":"Dark Stalker Worshiper","cr":7,"xp":3200,"race":"Dark stalker","age_category":"Adult","classes":[{"class":"rogue","level":3}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["dark folk"],"init":6,"senses":["see in darkness"],"ac":21,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+4 armor, +5 Dex, +2 natural","hp":70,"hd":"9d8+30","hd_value":9,"fort":6,"ref":14,"will":5,"defensive_abilities":["evasion","trap sense +1"],"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"mwk short sword +12 (1d6+4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"},{"type":"sneak attack","details":"+5d6"}],"spell_like_abilities_caster_level":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"deeper darkness"},{"spell":"detect magic"},{"spell":"fog cloud"}]}],"strength":18,"dexterity":22,"constitution":16,"intelligence":8,"wisdom":14,"charisma":10,"baseatk":6,"cmb":10,"cmd":26,"feats":[{"feat":"Double Slice"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Skill Focus (Perception)"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Climb","value":12},{"skill":"Disable Device","value":10},{"skill":"Perception","value":21},{"skill":"Stealth","value":27},{"skill":"Survival","value":6},{"skill":"Use Magic Device","value":4}],"languages":["Dark Folk","Undercommon"],"sq":["poison use","rogue talents (finesse rogue)","trapfinding +1"],"gear":"+1 shadow studded leather, masterwork short swords (2), 105 gp, potion of invisibility, black smear (6 doses), tanglefoot bag","before_combat":"If the dark stalker detects the PCs' approach, it attempts to hide behind the statue of its dark goddess. While hidden, it coats each of its blades with a dose of black smear.","during_combat":"When the PCs enter its unholy domain, the dark stalker touches the podium in front of it and casts deeper darkness, enveloping the entire room and some of the extending passages in impenetrable blackness. It relies on the cover of darkness to bring its enemies to their knees with its short swords. Should it find an opponent not susceptible to its sneak attack damage even under the cover of darkness, it moves on to more vulnerable targets.","morale":"The dark slayer defends its unholy shrine to the death.","source":"PFS S3-20, Pathfinder RPG Bestiary 54"},{"name":"Dark Slayer Meditator","cr":7,"xp":3200,"race":"Dark slayer","age_category":"Adult","classes":[{"class":"sorcerer","level":5}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["dark folk"],"init":5,"senses":["detect magic","see in darkness"],"ac":16,"ac_touch":16,"ac_flat_footed":11,"ac_mods":"+5 Dex, +1 size","hp":58,"hd":"4d8+5d6+23","hd_value":9,"fort":6,"ref":7,"will":8,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"+1 kukri +12 (1d3+2/18-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"},{"type":"poison use"},{"type":"sneak attack","details":"+2d6"},{"type":"soul harvest"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"bleed"},{"spell":"chill touch"},{"spell":"darkness"},{"spell":"spectral hand"}]},{"frequency":"3/day","spells":[{"spell":"daze monster"},{"spell":"death knell"},{"spell":"inflict moderate wounds"}]},{"frequency":"8/day","spells":[{"spell":"grave touch","details":"2 rounds"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":5,"spellsknown_concentration":10,"spellsknown":[{"spell_level":2,"spell_slots":5,"spells":[{"spell":"false life"},{"spell":"ghoul touch"},{"spell":"scorching ray"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"cause fear"},{"spell":"chill touch"},{"spell":"protection from good"},{"spell":"ray of enfeeblement"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"read magic"},{"spell":"touch of fatigue"}]}],"bloodline":"undead","strength":13,"dexterity":20,"constitution":14,"intelligence":8,"wisdom":11,"charisma":20,"baseatk":5,"cmb":5,"cmd":20,"feats":[{"feat":"Combat Casting"},{"feat":"Eschew Materials"},{"feat":"Great Fortitude"},{"feat":"Skill Focus (Use Magic Device)"},{"feat":"Spell Focus (necromancy)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":5},{"skill":"Perception","value":4},{"skill":"Spellcraft","value":6},{"skill":"Stealth","value":17},{"skill":"Use Magic Device","value":15}],"languages":["Dark Folk"],"sq":["bloodline arcana (corporeal undead affected by humanoid affecting spells)","magical knack"],"special_abilities":[{"type":"Death Throes","kind":"Su","details":"When a dark stalker is slain, its body implodes violently into nothingness, leaving its gear in a heap on the ground. All creatures within a 10-foot burst take 1d8 points of sonic damage and must succeed at a DC 14 Fortitude save or be deafened for 2d4 rounds. The save DC is Constitution-based."},{"type":"Soul Harvest","kind":"Su","details":"When a dark slayer damages a flat-footed foe or a foe it is flanking with a melee touch spell or spell like ability that deals hit point damage, the spell does an additional 1d6 points of damage and the dark slayer gains an equal number of temporary hit points. These temporary hit points last for a maximum of 1 hour."}],"gear":"+1 kukri, 322 gp, black smear (2 doses), scroll of deeper darkness, scroll of mage armor, wand of dispel magic (CL 11th, 6 charges)","before_combat":"The dark slayer is in a deep, trancelike meditative state and most likely unaware of the PCs' approach. Should it manage to hear the PCs before the encounter begins, it draws its wand and kukri.","during_combat":"The dark slayer attempts to sneak attack the PCs with ranged touch and melee touch spells, taking full advantage of its soul harvest ability. Should the PCs attempt to neutralize the deeper darkness effect in the shrine, the dark slayer uses its wand of dispel magic to negate the PCs' spells or effects.","morale":"The dark slayer defends its unholy shrine to the death.","source":"PFS S3-20, Pathfinder RPG Bestiary 2 75"},{"name":"Malfunctioning Repair Drone","cr":0.5,"xp":200,"race":"clockwork servant","age_category":"Adult","alignment":"N","size":"Medium","type":"construct","sub_types":["robot"],"init":0,"senses":["darkvision 60 ft.","low-light vision"],"ac":12,"ac_touch":10,"ac_flat_footed":12,"ac_mods":"+2 natural","hp":11,"hd":"2d10","hd_value":2,"fort":0,"ref":0,"will":0,"immunities":["construct traits"],"weaknesses":["malfunctioning","vulnerable to critical hits","vulnerable to electricity"],"speed":[{"type":"land","speed":30}],"melee":"slam +4 (1d4+2)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":10,"intelligence":10,"wisdom":11,"charisma":1,"baseatk":2,"cmb":4,"cmd":18,"feats":[{"feat":"Skill Focus (Knowledge engineering)"}],"skills":[{"skill":"Disable Device","value":4},{"skill":"Knowledge (engineering)","value":8},{"skill":"Perception","value":4}],"languages":["Androffan"],"special_abilities":[{"type":"Malfunctioning","kind":"Ex","details":"With its current damage and partial charge, the repair drone is effectively staggered, suffers a reduction to its Strength and Dexterity scores, and doesn't gain its bonus hit points for being a construct. Furthermore, three standard features to a repair drone (fast healing, the ability to repair robots, and its net) are missing."}],"during_combat":"The drone ignores the PCs and continues to tear the building apart, one stone at a time, but turns its wrath on any character who attempts to hurt it or even simply stands in its way. Unfortunately for the PCs, there are few ways to stop the thing from rampaging other than taking it out-if they ignore the robot, it continues to dismantle the building until several townsfolk team up to take it down (resulting, most likely, in several wounded citizens along the way).","morale":"Once it attacks, the drone fights until destroyed.","source":"AP 85, Pathfinder RPG Bestiary 3 56"},{"name":"Young Slime Mold","cr":0.3333,"xp":135,"race":"Young Slime Mold","age_category":"Adult","alignment":"N","size":"Small","type":"ooze","init":1,"ac":12,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+1 Dex, +1 size","hp":6,"hd":"1d8+2","hd_value":1,"fort":2,"ref":1,"will":-5,"immunities":["ooze traits"],"resists":["fire 10"],"speed":[{"type":"land","speed":30}],"melee":"slam +1 (1d3)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":12,"constitution":15,"wisdom":1,"charisma":1,"baseatk":0,"cmb":-1,"cmd":10,"sq":["freeze"],"source":"AP 85"},{"name":"Sef","cr":3,"xp":800,"race":"skulk","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":2}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["skulk"],"init":8,"senses":["low-light vision"],"ac":14,"ac_touch":14,"ac_flat_footed":10,"ac_mods":"+4 Dex","hp":32,"hd":"3d8+2d8+10","hd_value":5,"fort":3,"ref":10,"will":2,"defensive_abilities":["evasion"],"speed":[{"type":"land","speed":30}],"melee":"mwk short sword +8 (1d6/19-20)","ranged":"dagger +7 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":11,"dexterity":18,"constitution":15,"intelligence":12,"wisdom":12,"charisma":11,"baseatk":3,"cmb":3,"cmd":17,"feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":8},{"skill":"Disable Device","value":12},{"skill":"Knowledge (engineering)","value":4},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":9},{"skill":"Sleight of Hand","value":9},{"skill":"Stealth","value":23},{"skill":"Survival","value":6}],"languages":["Common","Undercommon"],"sq":["camouflaged step","chameleon skin","rogue talents (fast stealth)","trapfinding +1"],"gear":"daggers (10), mwk short sword, 35 gp, 18 sp, alchemist's fire (2), liquid ice, smokesticks (3)","during_combat":"Sef keeps hidden during combat for as long as she can and makes ranged sneak attacks. She does so by hurling flasks of alchemist's fire and thrown daggers before using her fast stealth rogue talent to move deeper into the shadows to hide again. If cornered, she lashes out with her short sword until she can break free and run, but always returns after eluding (or fooling) pursuit, waging guerrilla attacks to wear down her opposition.","morale":"Sef surrenders if reduced to fewer than 10 hit points, begging for mercy. She gives up all the information and treasures she has in return for the chance to slink away- whether or not she harbors a grudge and returns later to get revenge on the PCs is left to you to decide.","source":"AP 85, Pathfinder RPG Bestiary 2 248"},{"name":"Repair Drone","cr":2,"xp":600,"race":"clockwork servant","age_category":"Adult","alignment":"N","size":"Medium","type":"construct","sub_types":["robot"],"init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":31,"hd":"2d10+20","hd_value":2,"hp_mods":"fast healing 2","fort":0,"ref":2,"will":0,"immunities":["construct traits"],"weaknesses":["vulnerable to critical hits","vulnerable to electricity"],"speed":[{"type":"land","speed":30}],"melee":"slam +6 (1d4+6)","ranged":"net +4 (entangle)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":14,"intelligence":10,"wisdom":11,"charisma":1,"baseatk":2,"cmb":6,"cmd":18,"feats":[{"feat":"Skill Focus (Knowledge engineering)"}],"skills":[{"skill":"Disable Device","value":6},{"skill":"Knowledge (engineering)","value":8},{"skill":"Perception","value":4}],"languages":["Androffan"],"sq":["repair robot"],"special_abilities":[{"type":"Net","kind":"Ex","details":"A repair drone's net is constructed from polymer mesh-this functions as a normal net, save that it has 10 hit points and can be burst with a successful DC 27 Strength check. A polymer mesh net is worth 50 gp."},{"type":"Repair Robot","kind":"Ex","details":"As a standard action that doesn't provoke an attack of opportunity, a repair drone can repair damage dealt to either itself or an adjacent robot, healing the target of 1d10 points of damage."}],"gear":"polymer mesh nets (5)","source":"AP 85, Pathfinder RPG Bestiary 3 56"},{"name":"Kasatha Skeleton","cr":0.5,"xp":200,"race":"Kasatha","age_category":"Adult","alignment":"NE","size":"Medium","type":"undead","templates_applied":"@skeleton","init":8,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+4 Dex, +2 natural","hp":4,"hd":"1d8","hd_value":1,"fort":0,"ref":4,"will":2,"defensive_abilities":["rejuvenation"],"dr":"5/bludgeoning","immunities":["cold","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"4 claws +1 (1d4+1)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":19,"wisdom":10,"charisma":10,"baseatk":0,"cmb":1,"cmd":15,"feats":[{"feat":"Improved Initiative"}],"special_abilities":[{"type":"Rejuvenation","kind":"Ex","details":"Even if completely destroyed, the undead kasatha rejuvenate after 26 hours pass, their bones reconstituting from nothing if need be to carry on their undead existence. This perpetual cycle of eternal unlife persists until the habitat module's sky is reactivated, or until the remains of a defeated kasatha are put in an area where the rays of the rising sun can strike them."}],"source":"AP 85, Pathfinder RPG Bestiary 250, Pathfinder RPG Bestiary 4 174"},{"name":"Hetuath","cr":3,"xp":800,"race":"kasatha","age_category":"Adult","classes":[{"class":"fighter","level":3}],"alignment":"NE","size":"Medium","type":"undead","sub_types":["augmented kasatha"],"templates_applied":"juju zombie","init":8,"senses":["darkvision 60 ft."],"ac":20,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+4 Dex, +3 dodge, +3 natural","hp":30,"hd":"3d10+9","hd_value":3,"fort":5,"ref":6,"will":3,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1","channel resistance +4","defensive training","rejuvenation"],"dr":"5/magic and slashing","immunities":["cold","electricity","magic missile","undead traits"],"resists":["fire 10"],"speed":[{"type":"land","speed":30}],"melee":"mwk short sword +7 (1d6+4/19-20), mwk short sword +7 (1d6+2/19-20), 2 slams +2 (1d6+2)","ranged":"javelin +7 (1d6+4)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":18,"intelligence":8,"wisdom":12,"charisma":12,"baseatk":3,"cmb":7,"cmd":24,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Toughness"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Climb","value":8},{"skill":"Perception","value":5},{"skill":"Stealth","value":8}],"languages":["Kasatha"],"sq":["armor training 1","deathlink","desert runner","desert stride","jumper","multi-armed","stalker"],"special_abilities":[{"type":"Deathlink","kind":"Su","details":"Hetuath possesses a unique ability that allows him to see through the eye sockets of any of his seven undead tribesmen and to give simple commands to them while doing so. This ability has a maximum range of 1 mile, and as long as he's looking through the eye sockets of a skeleton, he remains fully aware of his own surroundings but can take no other action. He can end a link with a skeleton instantaneously."},{"type":"Rejuvenation","kind":"Ex","details":"Even if completely destroyed, an undead kasatha rejuvenates after a period of 26 hours passes, its bones reconstituting from nothing if need be to carry on its undead existence. This perpetual cycle of eternal unlife persists until the habitat module's sky is reactivated or the remains of a defeated kasatha are put in an area where the rays of the rising sun can strike them."}],"gear":"javelins (2), mwk short sword, mwk short sword, cloak of resistance +1, 40 gp","source":"AP 85, Pathfinder RPG Bestiary 4 174, Pathfinder RPG Bestiary 2 291","unique_monster":1},{"name":"Vrilledt","cr":3,"xp":800,"race":"Vegepygmy","age_category":"Adult","classes":[{"class":"fighter","level":2}],"alignment":"CE","size":"Small","type":"plant","init":7,"senses":["darkvision 60 ft.","low-light vision"],"ac":19,"ac_touch":14,"ac_flat_footed":16,"ac_mods":"+3 Dex, +5 natural, +1 size","hp":32,"hd":"1d8+2d10+17","hd_value":3,"fort":10,"ref":3,"will":3,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"dr":"5/slashing or bludgeoning","immunities":["electricity","plant traits"],"speed":[{"type":"land","speed":30}],"melee":"+1 light hammer +9 (1d4+5), claw +2 (1d4+2 plus spores)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":16,"constitution":20,"intelligence":12,"wisdom":17,"charisma":17,"baseatk":2,"cmb":5,"cmd":18,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (light hammer)"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Perception","value":9},{"skill":"Stealth","value":17,"special":"+12 in vegetation"}],"languages":["Undercommon","Vegepygmy (can't speak)"],"special_abilities":[{"type":"Spores","kind":"Ex","details":"Vrilledt infects those he hits with his claw with a less virulent strain of russet mold than normally found in this dangerous fungus. A creature hit can resist infection with a successful DC 15 Fortitude saving throw. If a creature fails this save, the slowly growing spores take root, and deal 2 points of Constitution damage per day. A new saving throw can be attempted each day to halt the growth. Once an infected creature dies (either from the spores themselves or another source), the body generates vegepygmies after 24 hours, as normal russet mold (Pathfinder RPG Bestiary 273). The save DC is Constitution-based."}],"gear":"+1 light hammer, 9 silverdisks","during_combat":"Vrilledt swiftly moves to melee with foes in combat, sending his two bodyguard vegepygmies to flank or even to provoke attacks of opportunity from enemies as needed so that he can move into more advantageous positions himself.","morale":"If reduced to fewer than 10 hit points, Vrilledt surrenders and begs for mercy, knowing that should he die, his spores die as well. He offers all his treasure as tribute to the PCs, and may even be convinced to aid them in defeating the robots, but the longer any alliance with the vegepygmy lasts, the more likely it is that he seizes an opportunity to betray the PCs.","source":"AP 85, Pathfinder RPG Bestiary 273, 294"},{"name":"Medical Drone","cr":2,"xp":600,"race":"clockwork servant","age_category":"Adult","alignment":"N","size":"Medium","type":"construct","sub_types":["robot"],"init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":31,"hd":"2d10+20","hd_value":2,"hp_mods":"fast healing 2","fort":0,"ref":2,"will":0,"immunities":["construct traits"],"weaknesses":["vulnerable to critical hits","vulnerable to electricity"],"speed":[{"type":"land","speed":30}],"melee":"claw +6 (1d4+6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"injection"}],"strength":19,"dexterity":14,"intelligence":10,"wisdom":11,"charisma":1,"baseatk":2,"cmb":6,"cmd":18,"feats":[{"feat":"Skill Focus (Heal)"}],"skills":[{"skill":"Heal","value":5},{"skill":"Perception","value":5}],"languages":["Androffan"],"sq":["repair robot"],"special_abilities":[{"type":"Injection","kind":"Su","details":"Up to three times per day as a swift action when it damages a living creature with its claw attack, a medical drone can inject that creature with a potion, poison, drug, or pharmaceutical. The drones in this adventure inject a local anesthetic that causes a -2 penalty to Strength that lasts for 1 hour (Fortitude DC 11 negates). This penalty stacks with multiple injections, but the duration doesn't. The save DC is Constitution-based."},{"type":"Repair Robot","kind":"Ex","details":"As a standard action that doesn't provoke an attack of opportunity, a repair drone can repair damage done to either itself or an adjacent robot, healing the target of 1d10 points of damage."}],"during_combat":"The drone speaks Androffan in a metallic voice as it attacks, spewing phrases like the following: \"Please remain calm; you are to undergo a medical procedure,\" or \"There is no reason to struggle, you are in safe hands,\" or \"The doctor will be with you shortly.\" The drone tries to inject its target with an anesthetic, hoping to maneuver a \"patient\" up onto one of the surgical beds. It doesn't pursue foes from this room unless attacked from beyond the room via ranged weapons.","morale":"The drone fights until destroyed.","source":"AP 85, Pathfinder RPG Bestiary 3 56"},{"name":"Garmen Ulreth","cr":3,"xp":800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":4}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":18,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+4 armor, +3 Dex, +1 shield","hp":25,"hd":"4d8+4","hd_value":4,"fort":2,"ref":7,"will":2,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"mwk rapier +7 (1d6/18-20)","ranged":"hand crossbow +6 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":10,"dexterity":16,"constitution":12,"intelligence":13,"wisdom":8,"charisma":16,"baseatk":3,"cmb":3,"cmd":16,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Improved Feint"},{"feat":"Iron Will"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Appraise","value":8},{"skill":"Bluff","value":10},{"skill":"Diplomacy","value":10},{"skill":"Disable Device","value":11},{"skill":"Intimidate","value":10},{"skill":"Knowledge (local)","value":8},{"skill":"Perception","value":6},{"skill":"Profession (gambler)","value":6},{"skill":"Sense Motive","value":6},{"skill":"Sleight of Hand","value":9},{"skill":"Stealth","value":9}],"languages":["Common","Hallit","Orc"],"sq":["rogue talents (finesse rogue, resiliency)","trapfinding +2"],"gear":"+1 studded leather, buckler, hand crossbow with 10 bolts, mwk rapier, mwk thieves' tools, 89 gp, potions of invisibility (2)","during_combat":"Garmen's first attack is against a flat-footed foe if possible. He drinks his potion of invisibility on the next round, repositions himself, and then sneak attacks the most wounded enemy he can reach. After this, he uses Improved Feint or flanking to maximize further sneak attacks.","morale":"If reduced to 10 or fewer hit points, Garmen drinks another potion of invisibility and then flees. He returns to Silverdisk Hall and plots revenge against the PCs, but if they show up looking for him before he can recover from his fight, he tries to avoid them. If cornered, Garmen surrenders and begs for mercy if reduced to 5 or fewer hit points.","source":"AP 85"},{"name":"Ropefist Thug","cr":0.5,"xp":200,"race":"human","age_category":"Adult","classes":[{"class":"rogue","level":1}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":14,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+3 armor, +1 Dex","hp":14,"hd":"1d8+6","hd_value":1,"fort":2,"ref":3,"will":-1,"speed":[{"type":"land","speed":30}],"melee":"unarmed strike +3 (1d3+4)","ranged":"sling +1 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":16,"dexterity":13,"constitution":15,"intelligence":10,"wisdom":8,"charisma":12,"baseatk":0,"cmb":3,"cmd":14,"feats":[{"feat":"Improved Unarmed Strike"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Bluff","value":5},{"skill":"Climb","value":7},{"skill":"Intimidate","value":5},{"skill":"Knowledge (local)","value":4},{"skill":"Perception","value":3},{"skill":"Sense Motive","value":3},{"skill":"Sleight of Hand","value":5},{"skill":"Stealth","value":5}],"languages":["Common"],"sq":["trapfinding +1"],"gear":"mwk studded leather, sling with 10 bullets, sunrod, 3d6 gp, potion of cure light wounds","during_combat":"The Ropefist thugs prefer to fight with their fists-they wrap their hands in coils of rope more as an affectation than anything else, and are equally good at pummeling foes with or without this decoration. They prefer to gang up on foes if possible. A thug drinks his potion of cure light wounds if reduced to 7 or fewer hit points.","morale":"A Ropefist thug who's reduced to 4 or fewer hit points attempts to flee, but if cornered, she fights to the death.","source":"AP 85"},{"name":"Scrapwall Fanatic","cr":1,"xp":400,"race":"Half-Orc","age_category":"Adult","classes":[{"class":"fighter","level":1},{"class":"rogue","level":1}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human","Orc"],"init":6,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+3 armor, +2 Dex, +1 shield","hp":17,"hd":"1d10+1d8+3","hd_value":2,"fort":3,"ref":4,"will":1,"defensive_abilities":["Orc ferocity"],"speed":[{"type":"land","speed":30}],"melee":"improvised weapon +4 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":17,"dexterity":14,"constitution":13,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":1,"cmb":4,"cmd":16,"feats":[{"feat":"Catch Off-Guard"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Climb","value":8},{"skill":"Intimidate","value":6},{"skill":"Perception","value":6},{"skill":"Stealth","value":7},{"skill":"Survival","value":6}],"languages":["Common","Orc"],"sq":["Orc blood","trapfinding +1"],"gear":"mwk studded leather, mwk buckler, brown access card, 2 silverdisks, 10 gp","during_combat":"These fanatics fight with jagged pieces of broken machinery, using these improvised weapons with surprising accuracy. When they're not able to flank foes, they prefer to attack the most wounded opponent in any group.","morale":"The fanatics live up to their name and fight to the death.","source":"AP 85"},{"name":"Ratfolk Scrapper","cr":0.5,"xp":200,"race":"Ratfolk","age_category":"Adult","classes":[{"class":"rogue","level":1}],"alignment":"CN","size":"Small","type":"humanoid","sub_types":["ratfolk"],"init":7,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 armor, +3 Dex, +1 size","hp":11,"hd":"1d8+3","hd_value":1,"fort":2,"ref":5,"will":-1,"speed":[{"type":"land","speed":20}],"melee":"short sword +1 (1d4/19-20)","ranged":"hand crossbow +4 (1d3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"},{"type":"swarming"}],"strength":10,"dexterity":16,"constitution":15,"intelligence":12,"wisdom":8,"charisma":13,"baseatk":0,"cmb":-1,"cmd":12,"feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Acrobatics","value":7,"special":"-4 when jumping"},{"skill":"Bluff","value":5},{"skill":"Climb","value":4},{"skill":"Craft (alchemy)","value":3},{"skill":"Disable Device","value":7},{"skill":"Handle Animal","value":2},{"skill":"Perception","value":5},{"skill":"Sleight of Hand","value":7},{"skill":"Stealth","value":11},{"skill":"Survival","value":0},{"skill":"Use Magic Device","value":3}],"languages":["Common","Orc"],"sq":["trapfinding +1"],"gear":"leather armor, hand crossbow with 10 bolts, short sword, brown access card, 2 gp, screaming bolt (1)","during_combat":"The ratfolk scrappers use their swarming ability to get sneak attacks, and prefer to attack Human foes over other targets if possible.","morale":"These ratfolk aren't as brave as the orcs working for Meyanda. A ratfolk reduced to 4 or fewer hit points attempts to flee or hide, but if cornered, fights to the death.","source":"AP 85, Pathfinder RPG Bestiary 3 231"}];
